html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Recibo de compra: lo que llegó de una orden de compra. Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Recibo de compra") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Proveedor", "nombre": doc.supplier_name or doc.supplier, "rfc": rfc_tercero("Supplier", doc.supplier), "direccion": direccion_lineas(doc.supplier_address)},
    [("Fecha de recepción", fecha_corta(doc.posting_date)),
     ("Orden de compra", (doc.items[0].purchase_order if doc.items else None)),
     ("Remisión del proveedor", doc.get("supplier_delivery_note")),
     ("Recibido en", doc.set_warehouse or (doc.items[0].warehouse if doc.items else None)),
     ("Moneda", doc.currency)]) }}
{%- set rechazo = doc.items | selectattr("rejected_qty") | list | length > 0 %}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Artículo</th>
        <th class="text-right" style="width:24mm">Recibido</th>
        {% if rechazo %}<th class="text-right" style="width:22mm">Rechazado</th>{% endif %}
        <th class="text-right" style="width:22mm">Precio</th>
        <th class="text-right" style="width:27mm">Importe</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ row.idx }}</td>
            <td>{{ oc.celda_articulo(row) }}</td>
            <td class="num">{{ cantidad_uom(row.received_qty or row.qty, row.uom or row.stock_uom) }}</td>
            {% if rechazo %}<td class="num">{{ cantidad_uom(row.rejected_qty, row.uom or row.stock_uom) if row.rejected_qty else "—" }}</td>{% endif %}
            <td class="num">{{ row.get_formatted("rate", doc) }}</td>
            <td class="num"><b>{{ row.get_formatted("amount", doc) }}</b></td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{{ oc.cierre(doc, mostrar_pagos=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
